-- Correlação NCM x anexos da LC 214/2025: exceções da lei passam a valer como exceção (antes contavam como inclusão),
-- códigos estreitados ao texto da lei e NBS do Anexo IX (serviços) retiradas da tabela de NCM.
ALTER TABLE "CorrelacaoNcm" ADD COLUMN IF NOT EXISTS "excecao" BOOLEAN NOT NULL DEFAULT false;

