-- Anexo IX, itens 22 a 31: serviços identificados pela NBS (1.14xx...), não por NCM (12 linhas)
DELETE FROM "CorrelacaoNcm" WHERE "anexo" = 'IX' AND "item_lei" BETWEEN 22 AND 31;

-- 2026: o IBS é cobrado pela alíquota ESTADUAL de 0,1% (LC 214/2025, art. 343). A divisão estado × município estava zerada.
UPDATE "TransicaoAno" SET "ibs_uf_aliquota" = 0.001, "ibs_mun_aliquota" = 0, "updatedAt" = now()
 WHERE "ano" = 2026 AND COALESCE("ibs_uf_aliquota", 0) = 0 AND COALESCE("ibs_mun_aliquota", 0) = 0;

-- cClassTrib 220001, 220002 e 220003: vigência encerrada em 01/01/2026 na tabela oficial (Portal da Conformidade Fácil, SVRS).
UPDATE "ClassTrib" SET "vigencia_fim" = '2026-01-01', "updatedAt" = now()
 WHERE "c_class_trib" IN ('220001', '220002', '220003') AND "vigencia_fim" IS NULL;
